struct Person {
    // 记录选手获得[1-10]各个分数的数量
    vector<int> score;
    // 统计用户的获得的总分
    int sum;
    // 记录选手id
    int index;
    Person() : score(11, 0), sum(0), index(0) {}
};
​
// 按照sum进行从大到小排序，sum相等按照score从大到小排序
bool cmp(Person a, Person b) {
  if (a.sum == b.sum) {
    for (int i = 10; i >= 0; i--) {
      if (a.score[i] != b.score[i]) {
        return a.score[i] > b.score[i];
      }
    }
  }
  return a.sum > b.sum;
}
