package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
​
​
// Person 结构体
type Person struct {
    score []int // 记录选手获得[1-10]各个分数的数量
    sum   int   // 统计用户的获得的总分
    index int   // 记录选手下标
}
​
// 比较函数：按照 sum 从大到小排序，sum 相等时按照 score 从大到小排序
func cmp(a, b Person) bool {
    if a.sum == b.sum {
        for i := 10; i >= 1; i-- {
            if a.score[i] != b.score[i] {
                return a.score[i] > b.score[i]
            }
        }
    }
    return a.sum > b.sum
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取第一行输入
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line)
    inputs := strings.Split(line, ",")
​
    m, _ := strconv.Atoi(inputs[0])
    n, _ := strconv.Atoi(inputs[1])
​
    // 判断数据合法性
    if n < 3 || n > 100 || m < 3 || m > 10 {
        fmt.Println(-1)
        return
    }
​
    // 初始化选手数据
    players := make([]Person, n)
    for i := 0; i < n; i++ {
        players[i] = Person{
            score: make([]int, 11),
            sum:   0,
            index: i,
        }
    }
​
    // 读取每轮分数
    for i := 0; i < m; i++ {
        line, _ := reader.ReadString('\n')
        line = strings.TrimSpace(line)
        scores := strings.Split(line, ",")
​
        for j, scoreStr := range scores {
            score, _ := strconv.Atoi(scoreStr)
​
            // 判断分数合法性
            if score < 1 || score > 10 {
                fmt.Println(-1)
                return
            }
​
            players[j].score[score]++
            players[j].sum += score
        }
    }
​
    // 排序选手
    sort.Slice(players, func(i, j int) bool {
        return cmp(players[i], players[j])
    })
​
    // 输出前三名选手的下标
    for i := 0; i < 3; i++ {
        if i > 0 {
            fmt.Print(",")
        }
        fmt.Print(players[i].index + 1)
    }
}
